                except OverflowError:
                    raise ValueError("ds became non-finite")
                if not math.isfinite(val):
                    raise ValueError("ds became non-finite")
                dsi[j] = val

    # dq[i][d] = Σ_j ds[i][j]*k[j][d]，每个 (i,d) 独立按 j 升序累加。
    dq = [[0.0] * D for _ in range(Tq)]
    for i in range(Tq):
        dsi = ds[i]
        dqi = dq[i]
