                    raise ValueError("dq accumulated to a non-finite value")
            dqi[d] = acc

    # dk[j][d] = Σ_i ds[i][j]*q[i][d]，每个 (j,d) 独立按 i 升序累加。
    dk = [[0.0] * D for _ in range(Tk)]
    for j in range(Tk):
